1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { CYCLES, monthlyCents, nextCharge } from '../src/cycles.js';
4	
5	test('every stored cycle name is known', () => {
6	  assert.ok(CYCLES.includes('monthly'));
7	  assert.ok(CYCLES.includes('yearly'));
8	});
9	
10	test('a monthly plan costs its price a month', () => {
11	  assert.equal(monthlyCents({ price: 1299, cycle: 'monthly' }), 1299);
12	  assert.equal(monthlyCents({ price: 0, cycle: 'monthly' }), 0);
13	});
14	
15	test('a yearly plan costs a twelfth of its price a month', () => {
16	  assert.equal(monthlyCents({ price: 12000, cycle: 'yearly' }), 1000);
17	  assert.equal(monthlyCents({ price: 2400, cycle: 'yearly' }), 200);
18	});
19	
20	test('the next charge of a plan that charges today is today', () => {
21	  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-08-24' }, '2026-10-24'), '2026-10-24');
22	  assert.equal(nextCharge({ cycle: 'yearly', since: '2025-10-24' }, '2026-10-24'), '2026-10-24');
23	});
24	
25	test('a plan that has not started yet next charges on its first day', () => {
26	  assert.equal(nextCharge({ cycle: 'monthly', since: '2026-11-05' }, '2026-10-24'), '2026-11-05');
27	});
